function enviarCandidatura(e){e.preventDefault();const v=vagaAtual();if(!v)return;const a=candidaturas(),email=$('#candEmail').value.trim().toLowerCase();if(a.some(c=>c.vagaId===v.id&&(c.email||'').toLowerCase()===email))return msg('#msgCandidatura','Você já se candidatou a esta vaga.');const c=candidatoLogado()||{},p=c.perfil||{},curr=ler(chaveCurriculo(),null),origem=$('#candCurriculoOpcao')?.value||'perfil';if(origem==='cadastrado'&&!curr)return msg('#msgCandidatura','Cadastre um currículo antes de selecionar esta opção.');a.unshift({id:'cand_'+Date.now(),vagaId:v.id,vagaTitulo:tituloVaga(v),candidato:$('#candNome').value.trim(),email:$('#candEmail').value.trim(),telefone:$('#candTelefone').value.trim(),mensagem:$('#candMensagem').value.trim(),curriculoOrigem:origem,curriculo:origem==='cadastrado'?curr:null,perfilProfissional:origem==='perfil'?{titulo:p.titulo||'',area:p.area||'',escolaridade:p.escolaridade||'',experiencia:p.experiencia||'',resumo:p.resumo||'',competencias:p.competencias||'',linkedin:p.linkedin||'',portfolio:p.portfolio||''}:null,status:'Em avaliação',criadoEm:new Date().toISOString()});gravar('empregaMaisCandidaturas',a);msg('#msgCandidatura','Candidatura enviada com sucesso.',true);setTimeout(()=>irPara('candidaturas'),800)}

function chaveCurriculo(){return'empregaMaisCurriculo_'+(sessionStorage.getItem('candidatoEmail')||'')}
function renderizarCurriculo(){const d=ler(chaveCurriculo(),null),n=$('#curriculoNomeExibicao'),det=$('#curriculoDetalheExibicao'),b=$('#curriculoBadge'),x=$('#btnExcluirCurriculo');if(!n)return;if(d){n.textContent=d.nome;det.textContent='Currículo cadastrado em '+new Date(d.data).toLocaleDateString('pt-BR');b.textContent='Cadastrado';b.className='curriculo-ok';x.classList.remove('oculto')}else{n.textContent='Nenhum currículo cadastrado';det.textContent='Envie um arquivo PDF, DOC ou DOCX.';b.textContent='Não cadastrado';b.className='';x.classList.add('oculto')}}
function salvarCurriculoLocal(e){e.preventDefault();const f=$('#arquivoCurriculo').files[0];if(!f)return;if(f.size>5*1024*1024)return msg('#msgCurriculo','O arquivo deve ter no máximo 5 MB.');const ext=(f.name.split('.').pop()||'').toLowerCase();if(!['pdf','doc','docx'].includes(ext))return msg('#msgCurriculo','Envie um arquivo PDF, DOC ou DOCX.');gravar(chaveCurriculo(),{nome:f.name,tamanho:f.size,tipo:f.type,data:new Date().toISOString()});msg('#msgCurriculo','Currículo cadastrado.',true);renderizarCurriculo()}
