const PLANOS_EMPRESA={basico:{nome:'Grátis',vagas:3,destaques:0,urgentes:0,confidenciais:0},mensal:{nome:'Mensal',vagas:6,destaques:1,urgentes:1,confidenciais:0},trimestral:{nome:'Trimestral',vagas:12,destaques:3,urgentes:3,confidenciais:2},semestral:{nome:'Semestral',vagas:25,destaques:5,urgentes:5,confidenciais:4},anual:{nome:'Anual',vagas:60,destaques:10,urgentes:10,confidenciais:8}};
function selecionarPlano(p){if(papelAtual()!=='empresa'){irPara('login-empresa');return}const empresas=ler('empregaMaisEmpresas'),cnpj=sessionStorage.getItem('empresaCnpj'),i=empresas.findIndex(e=>e.cnpj===cnpj);if(i<0)return;if(p==='basico'){empresas[i].plano='basico';gravar('empregaMaisEmpresas',empresas);msg('#msgPlano','Plano Grátis ativado.',true);return}msg('#msgPlano','Plano '+PLANOS_EMPRESA[p].nome+' selecionado. A integração de pagamento será conectada na etapa de backend.')}
function planoEmpresaAtual(){const c=sessionStorage.getItem('empresaCnpj'),e=ler('empregaMaisEmpresas').find(x=>x.cnpj===c);return PLANOS_EMPRESA[e?.plano]||PLANOS_EMPRESA.basico}function chaveMes(d){const x=new Date(d||Date.now());return x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')}function usoPlanoEmpresa(){const c=sessionStorage.getItem('empresaCnpj')||'',mes=chaveMes(),vs=ler('empregaMaisVagas').filter(v=>v.empresaCnpj===c&&chaveMes(v.criadoEm)===mes&&v.status!=='excluida');return{vagas:vs.length,destaques:vs.filter(v=>v.destaque).length,urgentes:vs.filter(v=>v.urgente).length,confidenciais:vs.filter(v=>v.confidencial).length}}function saldoPlano(){const p=planoEmpresaAtual(),u=usoPlanoEmpresa();return{plano:p,uso:u,vagas:Math.max(0,p.vagas-u.vagas),destaques:Math.max(0,p.destaques-u.destaques),urgentes:Math.max(0,p.urgentes-u.urgentes),confidenciais:Math.max(0,p.confidenciais-u.confidenciais)}}function atualizarOpcoesPlano(){const x=saldoPlano(),set=(id,t)=>{const e=$('#'+id);if(e)e.textContent=t};set('saldoDestaque','('+x.destaques+' disponível(is) no mês)');set('saldoUrgente','('+x.urgentes+' disponível(is) no mês)');set('saldoConfidencial','('+x.confidenciais+' disponível(is) no mês)');const r=$('#resumoPlanoPublicacao');if(r)r.innerHTML='<strong>Plano '+x.plano.nome+'</strong><span>'+x.vagas+' de '+x.plano.vagas+' publicação(ões) disponível(is) neste mês</span>';[['vagaDestaque','destaques'],['vagaUrgente','urgentes'],['vagaConfidencial','confidenciais']].forEach(([id,k])=>{const e=$('#'+id);if(e&&!e.checked)e.disabled=x[k]<=0});const a=$('#avisoLimitePlano');if(a)a.textContent=x.vagas<=0?'Você atingiu o limite de publicações do seu plano neste mês.':''}function validarRecursosPlano(dados,editId){const x=saldoPlano(),lista=ler('empregaMaisVagas'),ant=editId?lista.find(v=>v.id===editId):null;if(!editId&&x.vagas<=0)return'Limite mensal de vagas atingido para o plano '+x.plano.nome+'.';if(dados.destaque&&!(ant&&ant.destaque)&&x.destaques<=0)return'Seu plano não possui Destaque disponível neste mês.';if(dados.urgente&&!(ant&&ant.urgente)&&x.urgentes<=0)return'Seu plano não possui marcação Urgente disponível neste mês.';if(dados.confidencial&&!(ant&&ant.confidencial)&&x.confidenciais<=0)return'Seu plano não possui vaga Confidencial disponível neste mês.';return''}

function loginAdmin(e){e.preventDefault();const email=$('#adminEmail').value.trim().toLowerCase(),senha=$('#adminSenha').value;if(email==='admin@empregamais.local'&&senha==='admin'){sessionStorage.setItem('empregaMaisAdmin','1');irPara('painel-admin')}else msg('#msgLoginAdmin','Credenciais administrativas inválidas.')}
function sairAdmin(){sessionStorage.removeItem('empregaMaisAdmin');irPara('home')}
function adminAba(aba,btn){if(sessionStorage.getItem('empregaMaisAdmin')!=='1'){irPara('login-admin');return}document.querySelectorAll('[data-admin-tab]').forEach(b=>b.classList.toggle('ativo',b.dataset.adminTab===aba));const out=$('#adminConteudo'),vs=ler('empregaMaisVagas'),es=ler('empregaMaisEmpresas'),cs=ler('empregaMaisCandidatos'),cands=candidaturas();if(aba==='geral'){const pend=vs.filter(v=>v.status==='pendente').length,apr=vs.filter(v=>v.status==='aprovada').length,contr=cands.filter(c=>grupoEtapa(c.status)==='Contratados').length;out.innerHTML='<div class="admin-metricas"><article><span>Vagas pendentes</span><strong>'+pend+'</strong></article><article><span>Vagas publicadas</span><strong>'+apr+'</strong></article><article><span>Empresas</span><strong>'+es.length+'</strong></article><article><span>Candidatos</span><strong>'+cs.length+'</strong></article><article><span>Contratações</span><strong>'+contr+'</strong></article></div><div class="admin-bloco"><h2>Aguardando aprovação</h2>'+adminTabelaVagas(vs.filter(v=>v.status==='pendente'))+'</div>';return}if(aba==='vagas'){out.innerHTML='<div class="admin-bloco"><h2>Todas as vagas</h2>'+adminTabelaVagas(vs)+'</div>';return}if(aba==='empresas'){out.innerHTML='<div class="admin-bloco"><h2>Empresas cadastradas</h2>'+adminTabelaPessoas(es,'empresa')+'</div>';return}if(aba==='candidatos'){out.innerHTML='<div class="admin-bloco"><h2>Candidatos cadastrados</h2>'+adminTabelaPessoas(cs,'candidato')+'</div>';return}if(aba==='contratacoes'){const a=cands.filter(c=>grupoEtapa(c.status)==='Contratados');out.innerHTML='<div class="admin-bloco"><h2>Contratações registradas</h2>'+adminTabelaContratacoes(a)+'</div>';return}if(aba==='denuncias'){const ds=ler('empregaMaisDenuncias');out.innerHTML='<div class="admin-bloco"><h2>Denúncias de vagas</h2><p class="admin-sub">Analise os relatos enviados pelos usuários antes de tomar uma ação.</p>'+adminTabelaDenuncias(ds,vs)+'</div>';return}if(aba==='planos'){out.innerHTML='<div class="admin-bloco"><h2>Planos das empresas</h2>'+es.map(e=>'<div class="admin-linha"><div><strong>'+esc(e.nome||'Empresa')+'</strong><small>'+esc(e.cnpj||'')+'</small></div><select onchange="adminMudarPlano(\''+esc(e.cnpj||'')+'\',this.value)">'+Object.keys(PLANOS_EMPRESA).map(p=>'<option value="'+p+'" '+((e.plano||'basico')===p?'selected':'')+'>'+PLANOS_EMPRESA[p].nome+'</option>').join('')+'</select></div>').join('')+'</div>'}}
function adminTabelaVagas(a){return a.length?'<div class="admin-lista">'+a.map(v=>'<div class="admin-linha"><div><strong>'+esc(tituloVaga(v))+'</strong><small>'+esc(v.empresa||'')+' · '+esc(v.status||'')+'</small></div><div class="admin-acoes"><button class="btn" onclick="adminVerVaga(\''+v.id+'\')">Ver vaga</button>'+(v.status==='pendente'?'<button class="btn btn-azul" onclick="adminStatusVaga(\''+v.id+'\',\'aprovada\')">Aprovar</button><button class="btn" onclick="adminReprovarVagaMotivo(\''+v.id+'\')">Reprovar</button>':'')+(v.status==='aprovada'?'<button class="btn" onclick="adminStatusVaga(\''+v.id+'\',\'encerrada\')">Encerrar</button>':'')+'</div></div>').join('')+'</div>':'<div class="vagas-vazio">Nenhum registro encontrado.</div>'}
function adminVerVaga(id){const v=ler('empregaMaisVagas').find(x=>x.id===id),box=$('#adminVagaConteudo');if(!v||!box)return;box.innerHTML='<div class="admin-vaga-top"><span class="vaga-status '+esc(v.status||'')+'">'+esc(v.status||'')+'</span><h2>'+esc(tituloVaga(v))+'</h2><p>'+esc(v.empresa||'')+' · '+esc(v.cidade||'')+(v.estado?' - '+esc(v.estado):'')+'</p></div><div class="ficha-grid"><div class="ficha-linha"><span>Contrato</span><strong>'+esc(v.contrato||'Não informado')+'</strong></div><div class="ficha-linha"><span>Modalidade</span><strong>'+esc(v.modalidade||'Não informado')+'</strong></div><div class="ficha-linha"><span>Salário</span><strong>'+esc(v.salario||'A combinar')+'</strong></div><div class="ficha-linha"><span>Área</span><strong>'+esc(v.area||'Não informada')+'</strong></div></div><section><h3>Descrição</h3><p>'+esc(v.descricao||'Não informada').replace(/\n/g,'<br>')+'</p></section><section><h3>Requisitos</h3><p>'+esc(v.requisitos||'Não informados').replace(/\n/g,'<br>')+'</p></section><section><h3>Benefícios</h3><p>'+esc(v.beneficios||'Não informados').replace(/\n/g,'<br>')+'</p></section><div class="admin-moderacao">'+(v.status==='pendente'?'<button class="btn btn-azul" onclick="adminAprovarVagaDetalhe(\''+v.id+'\')">Aprovar vaga</button><button class="btn perigo" onclick="adminReprovarVagaMotivo(\''+v.id+'\')">Reprovar vaga</button>':'')+(v.status==='aprovada'?'<button class="btn" onclick="adminStatusVaga(\''+v.id+'\',\'encerrada\');fecharAdminVaga()">Encerrar vaga</button>':'')+'</div>';$('#modalAdminVaga').classList.remove('oculto')}function fecharAdminVaga(){$('#modalAdminVaga')?.classList.add('oculto')}function adminAprovarVagaDetalhe(id){adminStatusVaga(id,'aprovada');fecharAdminVaga()}function adminReprovarVagaMotivo(id){const motivo=prompt('Informe o motivo da reprovação para registro:');if(!motivo||!motivo.trim())return;const a=ler('empregaMaisVagas'),i=a.findIndex(v=>v.id===id);if(i<0)return;a[i].status='reprovada';a[i].motivoReprovacao=motivo.trim();a[i].atualizadoEm=new Date().toISOString();gravar('empregaMaisVagas',a);fecharAdminVaga();adminAba('vagas')}function adminTabelaDenuncias(ds,vs){return ds.length?'<div class="admin-lista">'+ds.map(d=>{const v=vs.find(x=>x.id===d.vagaId)||{};return '<div class="admin-linha denuncia-admin"><div><strong>'+esc(d.vaga||tituloVaga(v))+'</strong><small>'+esc(v.empresa||'')+' · '+esc(d.status||'pendente')+'</small><p>'+esc(d.motivo||'Motivo não informado')+'</p></div><div class="admin-acoes">'+((d.status||'pendente')==='pendente'?'<button class="btn btn-azul" onclick="adminResolverDenuncia(\''+d.id+'\',\'resolvida\')">Marcar resolvida</button><button class="btn" onclick="adminResolverDenuncia(\''+d.id+'\',\'descartada\')">Descartar</button>'+(v.id&&v.status==='aprovada'?'<button class="btn perigo" onclick="adminSuspenderPorDenuncia(\''+d.id+'\',\''+v.id+'\')">Suspender vaga</button>':''):'')+'</div></div>'}).join('')+'</div>':'<div class="vagas-vazio">Nenhuma denúncia recebida.</div>'}function adminResolverDenuncia(id,status){const a=ler('empregaMaisDenuncias'),i=a.findIndex(d=>d.id===id);if(i<0)return;a[i].status=status;a[i].analisadoEm=new Date().toISOString();gravar('empregaMaisDenuncias',a);adminAba('denuncias')}function adminSuspenderPorDenuncia(denId,vagaId){if(!confirm('Suspender esta vaga após analisar a denúncia?'))return;const vs=ler('empregaMaisVagas'),i=vs.findIndex(v=>v.id===vagaId);if(i>=0){vs[i].status='suspensa';vs[i].atualizadoEm=new Date().toISOString();gravar('empregaMaisVagas',vs)}adminResolverDenuncia(denId,'resolvida')}function adminTabelaPessoas(a,t){return a.length?'<div class="admin-lista">'+a.map(x=>'<div class="admin-linha"><div><strong>'+esc(x.nome||x.empresa||'')+'</strong><small>'+esc(x.email||'')+(t==='empresa'?' · '+esc(x.cnpj||''):'')+'</small></div></div>').join('')+'</div>':'<div class="vagas-vazio">Nenhum cadastro encontrado.</div>'}
function adminTabelaContratacoes(a){return a.length?'<div class="admin-lista">'+a.map(c=>{const v=ler('empregaMaisVagas').find(x=>x.id===c.vagaId)||{};return'<div class="admin-linha"><div><strong>'+esc(c.candidato||c.nome||'Candidato')+'</strong><small>'+esc(v.cargo||c.vagaTitulo||'')+' · '+esc(v.empresa||'')+'</small></div><span class="vaga-status aprovada">Contratado</span></div>'}).join('')+'</div>':'<div class="vagas-vazio">Nenhuma contratação registrada.</div>'}
function adminStatusVaga(id,status){const a=ler('empregaMaisVagas'),i=a.findIndex(v=>v.id===id);if(i<0)return;a[i].status=status;a[i].atualizadoEm=new Date().toISOString();gravar('empregaMaisVagas',a);adminAba('vagas')}
function adminMudarPlano(cnpj,p){const a=ler('empregaMaisEmpresas'),i=a.findIndex(e=>e.cnpj===cnpj);if(i<0)return;a[i].plano=p;gravar('empregaMaisEmpresas',a)}

function candidatoLogado(){const email=(sessionStorage.getItem('candidatoEmail')||'').toLowerCase();return ler('empregaMaisCandidatos').find(c=>(c.email||'').toLowerCase()===email)}function carregarPerfilCandidato(){const c=candidatoLogado();if(!c)return;const p=c.perfil||{},set=(id,v)=>{const e=$('#'+id);if(e)e.value=v||''};set('candPerfilNome',c.nome);set('candPerfilTelefone',c.telefone);set('candPerfilEmail',c.email);set('candPerfilCidade',c.cidade);set('candPerfilUf',c.uf);set('candPerfilNascimento',p.nascimento);set('candPerfilTitulo',p.titulo);set('candPerfilArea',p.area);set('candPerfilEscolaridade',p.escolaridade);set('candPerfilExperiencia',p.experiencia);set('candPerfilPretensao',p.pretensao);set('candPerfilModalidade',p.modalidade);set('candPerfilDisponibilidade',p.disponibilidade);set('candPerfilResumo',p.resumo);set('candPerfilCompetencias',p.competencias);set('candPerfilLinkedin',p.linkedin);set('candPerfilPortfolio',p.portfolio)}function salvarPerfilCandidato(e){e.preventDefault();const a=ler('empregaMaisCandidatos'),email=(sessionStorage.getItem('candidatoEmail')||'').toLowerCase(),i=a.findIndex(c=>(c.email||'').toLowerCase()===email);if(i<0)return;const v=id=>$('#'+id)?.value.trim()||'';a[i].nome=v('candPerfilNome');a[i].telefone=v('candPerfilTelefone');a[i].cidade=v('candPerfilCidade');a[i].uf=v('candPerfilUf').toUpperCase();a[i].perfil={nascimento:v('candPerfilNascimento'),titulo:v('candPerfilTitulo'),area:v('candPerfilArea'),escolaridade:v('candPerfilEscolaridade'),experiencia:v('candPerfilExperiencia'),pretensao:v('candPerfilPretensao'),modalidade:v('candPerfilModalidade'),disponibilidade:v('candPerfilDisponibilidade'),resumo:v('candPerfilResumo'),competencias:v('candPerfilCompetencias'),linkedin:v('candPerfilLinkedin'),portfolio:v('candPerfilPortfolio')};gravar('empregaMaisCandidatos',a);sessionStorage.setItem('candidatoNome',a[i].nome);msg('#msgPerfilCandidato','Perfil profissional atualizado.',true)}function atualizarPainelCandidato(){const email=(sessionStorage.getItem('candidatoEmail')||'').toLowerCase(),cs=candidaturas().filter(c=>(c.email||'').toLowerCase()===email),entrev=cs.filter(c=>grupoEtapa(c.status)==='Entrevista').length,salvas=JSON.parse(localStorage.getItem('empregaMaisSalvas_'+email)||'[]'),curr=localStorage.getItem('empregaMaisCurriculo_'+email);const mets=document.querySelectorAll('#pagina-painel-candidato .metrica strong');if(mets.length>=4){mets[0].textContent=curr?'Enviado':'Pendente';mets[1].textContent=cs.length;mets[2].textContent=entrev;mets[3].textContent=salvas.length}}function empresaLogada(){const c=sessionStorage.getItem('empresaCnpj');return ler('empregaMaisEmpresas').find(e=>e.cnpj===c)}
function abaPerfilEmpresa(tipo,btn){document.querySelectorAll('.perfil-tabs button').forEach(b=>b.classList.remove('ativo'));btn?.classList.add('ativo');$('#perfilPublico').classList.toggle('oculto',tipo!=='publico');$('#perfilConta').classList.toggle('oculto',tipo!=='conta')}
function carregarPerfilEmpresa(){const e=empresaLogada();if(!e)return;const p=e.perfil||{};['Nome','Segmento','Cidade','Uf','Porte','Fundacao','Slogan','Sobre','Missao','Visao','Valores','Cultura','Ambiente','Beneficios','Carreira','Modalidades','Areas','Site','Linkedin','Instagram','EmailPublico','Logo','Capa'].forEach(k=>{const el=$('#perfil'+k);if(el)el.value=p[k.charAt(0).toLowerCase()+k.slice(1)]||''});$('#perfilNome').value=p.nome||e.nome||'';$('#contaRazao').value=e.razao||'';$('#contaCnpj').value=e.cnpj||'';$('#contaResponsavel').value=e.responsavel||'';$('#contaEmail').value=e.email||'';$('#contaTelefone').value=e.telefone||'';$('#contaCep').value=e.cep||'';$('#contaCidade').value=e.cidade||'';$('#contaUf').value=e.uf||''}
function salvarPerfilEmpresa(evn){evn.preventDefault();const a=ler('empregaMaisEmpresas'),cnpj=sessionStorage.getItem('empresaCnpj'),i=a.findIndex(e=>e.cnpj===cnpj);if(i<0)return;const val=id=>$('#'+id)?.value.trim()||'';a[i].perfil={nome:val('perfilNome'),segmento:val('perfilSegmento'),cidade:val('perfilCidade'),uf:val('perfilUf').toUpperCase(),porte:val('perfilPorte'),fundacao:val('perfilFundacao'),slogan:val('perfilSlogan'),sobre:val('perfilSobre'),missao:val('perfilMissao'),visao:val('perfilVisao'),valores:val('perfilValores'),cultura:val('perfilCultura'),beneficios:val('perfilBeneficios'),carreira:val('perfilCarreira'),modalidades:val('perfilModalidades'),areas:val('perfilAreas'),site:val('perfilSite'),linkedin:val('perfilLinkedin'),instagram:val('perfilInstagram'),facebook:val('perfilFacebook'),video:val('perfilVideo'),ambiente:val('perfilAmbiente'),emailPublico:val('perfilEmailPublico'),logo:val('perfilLogo'),capa:val('perfilCapa')};Object.assign(a[i],{razao:val('contaRazao'),responsavel:val('contaResponsavel'),email:val('contaEmail'),telefone:val('contaTelefone'),cep:val('contaCep'),cidade:val('contaCidade'),uf:val('contaUf').toUpperCase()});gravar('empregaMaisEmpresas',a);sessionStorage.setItem('empresaNome',a[i].perfil.nome||a[i].nome);msg('#msgPerfilEmpresa','Perfil atualizado com sucesso.',true)}
function visualizarMinhaEmpresa(){const e=empresaLogada();if(!e)return;sessionStorage.setItem('empresaPublicaCnpj',e.cnpj);irPara('empresa-publica')}
function abrirEmpresaPublica(cnpj){sessionStorage.setItem('empresaPublicaCnpj',cnpj);irPara('empresa-publica')}
function renderizarEmpresaPublica(){const c=sessionStorage.getItem('empresaPublicaCnpj'),e=ler('empregaMaisEmpresas').find(x=>x.cnpj===c);if(!e){irPara('home');return}const p=e.perfil||{};$('#empresaPublicaNome').textContent=p.nome||e.nome||'Empresa';$('#empresaPublicaSlogan').textContent=p.slogan||'';const img=$('#empresaPublicaLogo');if(p.logo){img.src=p.logo;img.style.display='block'}else img.style.display='none';const capa=$('#empresaPublicaCapa');capa.style.backgroundImage=p.capa?'url("'+p.capa.replace(/"/g,'')+'")':'';$('#empresaPublicaInfo').innerHTML='<div><span>Matriz</span><strong>'+esc((p.cidade||e.cidade||'')+(p.uf||e.uf?' - '+(p.uf||e.uf):''))+'</strong></div><div><span>Funcionários</span><strong>'+esc(p.porte||'Não informado')+'</strong></div><div><span>Setor</span><strong>'+esc(p.segmento||'Não informado')+'</strong></div><div><span>Fundação</span><strong>'+esc(p.fundacao||'Não informado')+'</strong></div>';$('#empresaPublicaSobre').textContent=p.sobre||'A empresa ainda não adicionou uma apresentação.';$('#empresaPublicaInstitucional').innerHTML=[['Missão',p.missao],['Visão',p.visao],['Valores',p.valores],['Cultura',p.cultura],['Ambiente e jeito de trabalhar',p.ambiente],['Benefícios',p.beneficios],['Carreira e desenvolvimento',p.carreira],['Modalidades de trabalho',p.modalidades],['Áreas que mais contratam',p.areas]].filter(x=>x[1]).map(x=>'<h3>'+x[0]+'</h3><p>'+esc(x[1])+'</p>').join('');const links=$('#empresaPublicaLinks');if(links){const arr=[['Site',p.site],['LinkedIn',p.linkedin],['Instagram',p.instagram],['Facebook',p.facebook],['Vídeo institucional',p.video],['E-mail',p.emailPublico?'mailto:'+p.emailPublico:'']].filter(x=>x[1]);links.innerHTML=arr.map(x=>'<a class="btn" target="_blank" rel="noopener" href="'+esc(x[1])+'">'+x[0]+'</a>').join('')} const vs=ler('empregaMaisVagas').filter(v=>v.status==='aprovada'&&(v.empresaCnpj===c||v.cnpj===c)&&!v.confidencial);$('#empresaPublicaQtd').textContent=vs.length;$('#empresaPublicaVagas').innerHTML=vs.length?vs.map(v=>'<article class="vaga-card portal-vaga" onclick="abrirVaga(\''+v.id+'\')"><span class="tag">'+esc(v.modalidade||'Vaga')+'</span><h3>'+esc(v.cargo)+'</h3><p>'+esc(v.cidade||'')+'</p></article>').join(''):'<div class="vagas-vazio">Nenhuma vaga aberta no momento.</div>'}

function renderizarVagasSenior(){const box=$('#listaVagasSenior');if(!box)return;const a=ler('empregaMaisVagas').filter(v=>v.status==='aprovada'&&v.senior50);box.innerHTML=a.length?a.map(v=>'<article class="vaga-card portal-vaga" onclick="abrirVaga(\''+v.id+'\')"><span class="tag">50+</span><h3>'+esc(tituloVaga(v))+'</h3><p>'+esc(v.confidencial?'Empresa confidencial':v.empresa||'')+'</p><div class="vaga-meta"><span>'+esc(v.cidade||'')+'</span><span>'+esc(v.modalidade||'')+'</span></div></article>').join(''):'<div class="vagas-vazio"><strong>Nenhuma vaga 50+ publicada agora</strong><span>Novas oportunidades aparecerão aqui quando forem aprovadas.</span></div>'}
function filtrarSenior(){renderizarVagasSenior();document.querySelector('#listaVagasSenior')?.scrollIntoView({behavior:'smooth'})}
